                {"requestId":"r3","model":"m1","fromVersion":"1.0.0","toVersion":"2.0.0","ratio":10,
                "baseDigest":"%s","patchDigest":"%s","targetDigest":"%s"}
                """.formatted("g".repeat(64), DIGEST_P, DIGEST_T)))
